<template>
  <div class="typing-tutor w-full max-w-4xl mx-auto">
    <div class="header">
      <div class="title">긴 글 연습</div>
    </div>

    <div class="stats-bar">
      <div class="stat-box">
        <div class="stat-title">진행 시간</div>
        <div class="stat-value">{{ formattedTime }}</div>
      </div>
      <div class="stat-box">
        <div class="stat-title">현재 타수</div>
        <div class="stat-value">{{ cpm }}</div>
      </div>
      <div class="stat-box">
        <div class="stat-title">정확도</div>
        <div class="stat-value">{{ accuracy.toFixed(1) }} %</div>
      </div>
    </div>

    <div class="main-content">
      <div v-for="(line, lineIndex) in longText" :key="lineIndex">
        <p>{{longText[lineIndex]['chapter_text']}}</p>
        <div v-for="(verse, idx) in longText[lineIndex]['verse_list']" :key="idx" class="text-block">
          <div v-if="verse['text']" class="source-text">
            <span v-for="(char, idx) in verse['text'].split('')" :key="idx">{{char}}</span>
          </div>  
          <div 
            v-if="verse"
            class="input-text typing-font" 
            :contenteditable="currentActiveLine === (verse.verseIndx)"
            :class="{ active: currentActiveLine === (verse.verseIndx) }"
            @keydown.enter.prevent="checkLine(verse.verseIndx)"
            @input="updateLine(verse.verseIndx, $event)"
            @blur="handleBlur"
            ref="inputFields"
            :data-line-index="verse.verseIndx"  
          ></div>
          <div v-else class="source-text">&nbsp;</div>
        </div>
      </div>
    </div>

    <div class="notification" :class="{ warning: notificationWarning }" v-show="notification !=''">
      {{ notification }}
    </div>
  </div>
</template>
<script>
export default {
  name: "TypingTutor",

  data() {
    return {
      longText: [
        {
          text : "",
          typed : false,
        }
      ],
      flatLongText : [],
      chapterList : [],
      typedLines: [],
      currentActiveLine: 0,
      practiceStarted: false,
      startTime: 0,
      elapsedTimeValue: 0, // 실시간 시간 저장을 위한 데이터
      timerInterval: null,
      notification: "",
      notificationWarning: false,
      diffResults : [],
      bookAll : [
        { book: 1, chapter: 1, verse:1, script: "동해물과 백두산이 마르고 닳도록 " },
        { book: 1, chapter: 1, verse:2, script: "남산 위에 저 소나무 철갑을 두른 " },
        { book: 1, chapter: 1, verse:3, script: "가을 하늘 공활한데 높고 구름 없" },
        { book: 1, chapter: 1, verse:4, script: "이 기상과 이 맘으로 충성을 다하" },
      ],
    };
  },
  computed: {
    formattedTime() {
      const minutes = Math.floor(this.elapsedTimeValue / 60);
      const seconds = this.elapsedTimeValue % 60;
      return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
    },
    cpm() {
      let totalCorrect = this.countChars().totalCorrect;
      return this.elapsedTimeValue > 0 ? Math.floor((totalCorrect / this.elapsedTimeValue) * 60) : 0;
    },
    accuracy() {
      let { totalCorrect, totalTyped } = this.countChars();
      return totalTyped > 0 ? (totalCorrect / totalTyped) * 100 : 100;
    }
  },
  methods: {
    typing_book() {
      let allBook = this.bookAll;
      let filterAllBook = allBook.filter(item=>{
        return item.book == this.$route.query.book && item.chapter == this.$route.query.chapter
      });
      return filterAllBook
    },
    // 공통 계산 로직을 함수로 분리하여 중복 제거
    countChars() {
      let totalCorrect = 0;
      let totalTyped = 0;
      this.typedLines.forEach((line, idx) => {
        if (!line) return;
        const source = this.flatLongText[idx]['text'];
        totalTyped += line.length;
        for (let i = 0; i < line.length; i++) {
          if (line[i] === source[i]) totalCorrect++;
        }
      });
      return { totalCorrect, totalTyped };
    },

    setActiveLine(index) {
      // 1. 어떤 줄이 활성화될지 데이터를 먼저 변경합니다.
      this.currentActiveLine = index;

      // 2. Vue가 이 데이터 변경을 화면에 적용할 때까지 기다립니다.
      this.$nextTick(() => {
        // 3. 화면 업데이트가 완료된 후, 모든 입력창($refs.inputFields) 중에서
        //    활성화해야 할 줄(index)과 동일한 data-line-index를 가진 div를 찾습니다.
        if (this.$refs.inputFields) {
            const fieldToFocus = this.$refs.inputFields.find(el => parseInt(el.dataset.lineIndex) === index);
            console.log(fieldToFocus);
            
            // 4. 정확히 찾은 그 div에 포커스를 줍니다.
            if (fieldToFocus) {
              fieldToFocus.focus();
            }
        }
      });
    },
    updateLine(index, event) {
      if (!this.practiceStarted) this.startPractice();
      
      this.$set(this.typedLines, index, event.target.textContent);
    },
    checkLine(index) {
      const typed = (this.typedLines[index] || "").trim();
      const source = this.flatLongText[index]['text'].trim();
      console.log(index);
      if (typed === source) {
        // 정답 → 다음 줄로 이동
        this.nextLine(index);
      } else {
        // 오답 → 알림 & 틀린 줄 강조
        this.notification = "틀렸습니다. 다시 입력하세요.";
        this.notificationWarning = true;

        // 입력창 배경 빨갛게 표시
        const field = this.$refs.inputFields.find(el => parseInt(el.dataset.lineIndex) === index);
        if (field) {
          field.style.backgroundColor = "#fdd"; // 오답 강조
          setTimeout(() => field.style.backgroundColor = "", 800); // 잠깐 깜빡이고 원래대로
        }
      }
    },
    nextLine(index) {
      const typed = this.typedLines[index] || "";
      const source = this.flatLongText[index]['text'];

      let diff = [];

      for (let i = 0; i < source.length; i++) {
        if (typed[i] === undefined) {
          diff.push("missing"); // 입력 안 함
        } else if (typed[i] === source[i]) {
          diff.push("correct"); // 맞음
        } else {
          diff.push("incorrect"); // 틀림
        }
      }

      this.$set(this.diffResults, index, diff);

      const nextLineIndex = this.findNextPracticeLine(index + 1);
      if (nextLineIndex !== null) {
        this.setActiveLine(nextLineIndex);
        this.notification = "";
      } else {
        this.endPractice();
      }
    },
    // 비어있지 않은 다음 연습 줄을 찾는 함수
    findNextPracticeLine(startIndex) {
      for (let i = startIndex; i < this.flatLongText.length; i++) {
        if (this.flatLongText[i]['text']) return i;
      }
      return null;
    },
    startPractice() {
      this.practiceStarted = true;
      this.startTime = Date.now();
      this.timerInterval = setInterval(() => {
        this.elapsedTimeValue = Math.floor((Date.now() - this.startTime) / 1000);
      }, 1000);
    },
    endPractice() {
      clearInterval(this.timerInterval);
      this.notification = `연습 종료! 최종 타수: ${this.cpm}, 정확도: ${this.accuracy.toFixed(1)}%`;
      this.practiceStarted = false;
      this.currentActiveLine = null; // 모든 필드 비활성화
    },
    // 포커스를 잃었을 때 호출되는 핸들러
    handleBlur() {
      let index = this.currentActiveLine;
      console.log(index)
      if(index == 0){
        if (this.$refs.inputFields) {
          const fieldToFocus = this.$refs.inputFields.find(el => parseInt(el.dataset.lineIndex) === index);
          // 4. 정확히 찾은 그 div에 포커스를 줍니다.
          if (fieldToFocus) {
            fieldToFocus.focus();
          }
        }
      }
      setTimeout(() => {
        if (this.practiceStarted && this.currentActiveLine !== null) {
          if (this.$refs.inputFields) {
            const fieldToFocus = this.$refs.inputFields.find(el => parseInt(el.dataset.lineIndex) === index);
            // 4. 정확히 찾은 그 div에 포커스를 줍니다.
            if (fieldToFocus) {
              fieldToFocus.focus();
            }
        }
        }
      }, 0);
    }
  },
  mounted() {
    let book_all_list = [];
    let filter_data = this.typing_book();
    let verseIndx = 0;
    for (let i = 0; i < filter_data.length; i++) {
      let verse_list = [];
      let { book, chapter, verse, script } = filter_data[i];
      book_all_list[i] = {
        chapter_text : book + ":" + chapter + "장" + verse + "절",
        verse_list : []
      }
      let text = script;
      for (let j = 0; j < text.length; j += 40) {
        console.log(verseIndx)
        let script_txt = text.substring(j, j + 40);
        const chars = script_txt.split("")
        // 글자의 30% 정도를 랜덤으로 가리기
        // 여기에 수치값을 높이면 랜덤이 많아지고, 수치를 낮추면 랜덤이 적어지는 것으로 난이도 조절 가능
        const masked = chars.map(char => {
          if (char === " ") return " " // 공백은 그대로
          return Math.random() < 0.1 ? "_" : char
        });
        verse_list.push({
          typed : true,
          text : masked.join(''),
          verseIndx : verseIndx,
        });
        verseIndx++;
      }
      book_all_list[i].verse_list = verse_list;
    }
    console.log(book_all_list);
    this.longText = book_all_list;

    let temp_array = [];
    if(book_all_list.length == 0) {
      temp_array = [];
    }
    for(let item of book_all_list){
        for(let subItem of item.verse_list){
            temp_array.push(subItem);
        }
    }

    this.flatLongText = temp_array;

    this.$nextTick(() => {
      const firstLine = this.findNextPracticeLine(0);
      if (firstLine !== null) {
        this.setActiveLine(firstLine);
      }
    });
  }
};
</script>

